create or replace function pg_temp.genan_journey_regression() returns jsonb language plpgsql security invoker as $test$
declare a uuid; p uuid:=gen_random_uuid(); d uuid:=gen_random_uuid(); c uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); req uuid; oid uuid; fid uuid; response jsonb; other jsonb; items jsonb; coupon text; results jsonb:='[]'; stage text;
begin select user_id into a from public.user_roles where role='admin' limit 1;
begin
stage:='create category, brand and atomic color/size product';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','aal','aal1')::text,true);
 perform set_config('request.jwt.claim.sub',a::text,true); perform set_config('role','authenticated',true);
 insert into public.categories(id,name,name_ar,slug,is_active,countries) values(c,'QA journey','اختبار مؤقت','qa-'||c,true,array['GLOBAL']);
 insert into public.brands(id,name,slug,is_active,countries) values(b,'QA journey','qa-'||b,true,array['GLOBAL']);
 perform public.admin_save_product(p,jsonb_build_object('name','QA journey','name_ar','اختبار رحلة شراء مؤقت','slug','qa-'||p,'price',100,'is_active',true,'is_featured',false,'is_best_seller',false,'in_stock',true,'stock_quantity',7,'discount',0,'category_id',c,'category','qa-'||c,'brand_id',b,'brand','QA journey','countries',array['GLOBAL'],'section_ids','[]'::jsonb,'home_collections','[]'::jsonb,'has_sizes',true,'sizes',array['M','L'],'color_variants',jsonb_build_array(jsonb_build_object('name','Red','hex','#ff0000','images',jsonb_build_array('/placeholder.svg'),'sizes',array['M','L'],'stock',7)),'accessories','[]'::jsonb,'features','[]'::jsonb,'specs','[]'::jsonb,'has_quality_variants',false,'quality_variants','[]'::jsonb),30,'[{"variant_key":"color:0:red:size:m","label":"Red M","color_name":"Red","color_hex":"#ff0000","size":"M","stock_quantity":4,"is_default":false},{"variant_key":"color:0:red:size:l","label":"Red L","color_name":"Red","color_hex":"#ff0000","size":"L","stock_quantity":3,"is_default":false}]',true);
 insert into public.delivery_companies(id,name,country,base_fee,service_scope,is_active) values(d,'QA journey','YE',5,'aden',true);
assert (select stock_quantity=7 and has_sizes from public.products where id=p); assert (select count(*)=2 from public.inventory_skus where product_id=p); assert (select cost_price=30 from public.product_costs where product_id=p);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='guest catalog visibility';
perform set_config('request.jwt.claims','{"role":"anon"}',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('role','anon',true);assert exists(select 1 from public.products where id=p and is_active); assert exists(select 1 from public.categories where id=c); assert exists(select 1 from public.brands where id=b);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='missing variant rejected';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'variant_selection_required' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='negative quantity rejected';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',-1,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'invalid_quantity' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='null quantity rejected';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',null,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'invalid_quantity' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='invalid color rejected';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Blue','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'variant_selection_required' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='stock excess rejected';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',5,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'insufficient_stock' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='duplicate lines cannot exceed SKU stock';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',3,'selected_color','Red','selected_size','M'))||jsonb_build_array(jsonb_build_object('product_id',p,'quantity',3,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'insufficient_stock' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='unknown accessory rejected';
begin perform public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Red','selected_size','M','selected_accessories',jsonb_build_array(jsonb_build_object('name','unknown','quantity',1)))),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm <> 'invalid_accessory' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='buy final units; server price and shipping';
req:=gen_random_uuid(); items:=jsonb_build_array(jsonb_build_object('product_id',p,'quantity',4,'selected_color','Red','selected_size','M','price',0.01)); response:=public.create_secure_order_v4(req,'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',items,'cod','SAR','SAR',null,d)::jsonb; oid:=(response->>'order_id')::uuid; assert (response->>'subtotal')::numeric=400; assert (response->>'total')::numeric=405; assert response->>'order_number' like 'GN-%';
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='idempotent checkout retry';
other:=public.create_secure_order_v4(req,'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',items,'cod','SAR','SAR',null,d)::jsonb; assert other->>'order_id'=response->>'order_id';
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='idempotency key rejects altered basket';
begin perform public.create_secure_order_v4(req,'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm<>'idempotency_key_reused' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='private order tracking';
assert public.get_order_tracking(response->>'order_number','wrong-token') is null; assert public.get_order_tracking(response->>'order_number',response->>'tracking_token')->>'order_number'=response->>'order_number';
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='checkout reserves exact SKU once';
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','aal','aal1')::text,true); perform set_config('request.jwt.claim.sub',a::text,true); perform set_config('role','authenticated',true);assert (select stock_quantity=0 from public.inventory_skus where product_id=p and size='M'); assert (select stock_quantity=3 from public.inventory_skus where product_id=p and size='L'); assert (select stock_reserved_at is not null from public.orders where id=oid);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='invoice data and review saved';
update public.orders set invoice_review_status='accepted' where id=oid; assert (select o.total=405 and jsonb_array_length(o.items)=1 from public.orders o where o.id=oid); assert exists(select 1 from public.orders_archive where original_order_id=oid);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='confirmation does not debit again';
update public.orders set status='confirmed' where id=oid; assert (select stock_quantity=0 from public.inventory_skus where product_id=p and size='M');
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='cancellation restores exact color and size';
update public.orders set status='cancelled' where id=oid; assert (select stock_quantity=4 from public.inventory_skus where product_id=p and size='M'); assert (select stock_quantity=7 from public.products where id=p);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='repeated cancellation cannot restore twice';
update public.orders set status='cancelled' where id=oid; assert (select stock_quantity=4 from public.inventory_skus where product_id=p and size='M');
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='cancelled order cannot be reopened';
begin update public.orders set status='confirmed' where id=oid; raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm<>'cancelled_order_is_final' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='active coupon creation';
coupon:='QA-'||replace(gen_random_uuid()::text,'-',''); insert into public.coupons(code,type,value,is_active,countries) values(coupon,'percentage',10,true,array['GLOBAL']);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='checkout coupon totals';
perform set_config('request.jwt.claims','{"role":"anon"}',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('role','anon',true);response:=public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',2,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',coupon,d)::jsonb; oid:=(response->>'order_id')::uuid; assert (response->>'subtotal')::numeric=200; assert (response->>'discount_amount')::numeric=20; assert (response->>'total')::numeric=185;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='order processing and delivery preserves reservation';
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','aal','aal1')::text,true); perform set_config('request.jwt.claim.sub',a::text,true); perform set_config('role','authenticated',true);update public.orders set status='confirmed' where id=oid; update public.orders set status='processing' where id=oid; update public.orders set status='shipped' where id=oid; update public.orders set status='delivered' where id=oid; assert (select stock_quantity=2 from public.inventory_skus where product_id=p and size='M');
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='partial refund returns one unit';
fid:=public.create_refund_request(oid,null,null,null,null,90,'QA rollback','cash',null,jsonb_build_array(jsonb_build_object('product_id',p,'refund_quantity',1,'selected_size','M','selected_color','Red')),'SAR','partial'); perform public.update_refund_status(fid,'approved','QA rollback'); perform public.update_refund_status(fid,'processing','QA rollback'); perform public.update_refund_status(fid,'completed','QA rollback'); assert (select stock_quantity=3 from public.inventory_skus where product_id=p and size='M');
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='completed refund cannot be replayed';
begin perform public.update_refund_status(fid,'completed','QA rollback'); raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm<>'Completed refund is final' then raise; end if; end; assert (select stock_quantity=3 from public.inventory_skus where product_id=p and size='M');
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='over-refund quantity rejected';
begin perform public.create_refund_request(oid,null,null,null,null,90,'QA rollback','cash',null,jsonb_build_array(jsonb_build_object('product_id',p,'refund_quantity',2,'selected_size','M','selected_color','Red')),'SAR','partial'); raise exception 'UNEXPECTED_SUCCESS'; exception when others then if sqlerrm<>'Refund quantity exceeds remaining refundable quantity' then raise; end if; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='remaining refund restores original inventory';
fid:=public.create_refund_request(oid,null,null,null,null,90,'QA rollback','cash',null,jsonb_build_array(jsonb_build_object('product_id',p,'refund_quantity',1,'selected_size','M','selected_color','Red')),'SAR','partial'); perform public.update_refund_status(fid,'approved','QA rollback'); perform public.update_refund_status(fid,'processing','QA rollback'); perform public.update_refund_status(fid,'completed','QA rollback'); assert (select stock_quantity=4 from public.inventory_skus where product_id=p and size='M'); assert (select stock_quantity=7 from public.products where id=p);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='currency SAR';
perform set_config('request.jwt.claims','{"role":"anon"}',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('role','anon',true);begin response:=public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb; assert response->>'currency_mode'='SAR'; assert response->>'currency_code'='SAR'; assert (response->>'total')::numeric=105*1; raise exception using errcode='PZ002',message='rollback currency fixture'; exception when sqlstate 'PZ002' then null; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='currency YER_SOUTH';
perform set_config('request.jwt.claims','{"role":"anon"}',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('role','anon',true);begin response:=public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Red','selected_size','M')),'cod','YER_SOUTH','YER_SOUTH',null,d)::jsonb; assert response->>'currency_mode'='YER_SOUTH'; assert response->>'currency_code'='YER_S'; assert (response->>'total')::numeric=105*550; raise exception using errcode='PZ002',message='rollback currency fixture'; exception when sqlstate 'PZ002' then null; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='currency YER_NORTH';
perform set_config('request.jwt.claims','{"role":"anon"}',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('role','anon',true);begin response:=public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA rollback address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Red','selected_size','M')),'cod','YER_NORTH','YER_NORTH',null,d)::jsonb; assert response->>'currency_mode'='YER_NORTH'; assert response->>'currency_code'='YER_N'; assert (response->>'total')::numeric=105*700; raise exception using errcode='PZ002',message='rollback currency fixture'; exception when sqlstate 'PZ002' then null; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='anonymous admin write is denied';
assert not has_function_privilege('anon','public.admin_save_product(uuid,jsonb,numeric,jsonb,boolean)','EXECUTE');
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));
stage:='inventory remains synchronized';
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','aal','aal1')::text,true); perform set_config('request.jwt.claim.sub',a::text,true); perform set_config('role','authenticated',true);assert (select stock_quantity=(select sum(stock_quantity) from public.inventory_skus where product_id=p) from public.products where id=p);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));

stage:='manual invoice confirmation and cancellation do not change stock';
perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','aal','aal1')::text,true); perform set_config('request.jwt.claim.sub',a::text,true); perform set_config('role','authenticated',true);
oid:=gen_random_uuid();
insert into public.orders(id,order_number,customer_name,customer_phone,customer_address,country,customer_city,items,subtotal,delivery_fee,total,total_base,payment_method,status,currency_mode,currency_code)
values(oid,'QA-MANUAL-'||oid,'QA rollback','+967700000001','QA rollback','YE','عدن','[{"product_id":"manual-qa-1","product_name":"QA manual","quantity":1,"price":10}]',10,0,10,10,'cod','pending','SAR','SAR');
update public.orders set status='confirmed' where id=oid;
update public.orders set status='cancelled' where id=oid;
assert (select stock_quantity=7 from public.products where id=p);
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));

stage:='size price adjustment comes from server rule';
begin
insert into public.size_price_rules(id,name,adjustments,is_active) values(b,'QA rule','{"M":10}',true);
update public.products set size_price_rule_id=b where id=p;
perform set_config('request.jwt.claims','{"role":"anon"}',true); perform set_config('request.jwt.claim.sub','',true); perform set_config('role','anon',true);
response:=public.create_secure_order_v4(gen_random_uuid(),'QA journey','+967700000001','QA address',null,'YE','عدن','عدن',jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1,'selected_color','Red','selected_size','M')),'cod','SAR','SAR',null,d)::jsonb;
assert (response->>'subtotal')::numeric=110;
assert (response->>'total')::numeric=115;
raise exception using errcode='PZ002',message='rollback price rule fixture';
exception when sqlstate 'PZ002' then null; end;
results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','PASS'));

raise exception using errcode='PZ001',message='Rollback all journey fixtures';
exception when sqlstate 'PZ001' then null;
when assert_failure then results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','FAIL','error',sqlerrm,'code',sqlstate));
when others then results:=results||jsonb_build_array(jsonb_build_object('name',stage,'status','FAIL','error',sqlerrm,'code',sqlstate));
end;
return results;
end;$test$;
select pg_temp.genan_journey_regression() as results;